#!/usr/bin/env node
/* Books-2 pathology wave 4: Robbins Basic Pathology 9th, Ch 6/10/11/13-17 (part).
 * Text chunks in /tmp/books2-work/robbins/ ground authoring; all prose in own
 * words, no verbatim copy. New MCQs only (bk2-pat-361 to 450). */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Robbins Basic Pathology 9th Edition (topic map; text rewritten, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("pat-nonclassic-inheritance", "Non Mendelian inheritance: imprinting, repeats and mitochondria", "nonmendelian_imprinting_repeats_mitochondrial", "Non Mendelian Inheritance: Imprinting, Repeats and Mitochondria",
 ["Genomic imprinting and UPD", "Trinucleotide repeats and anticipation", "Mitochondrial inheritance", "Mosaicism and counselling"],
 [step("**Genomic imprinting** silences alleles by parent of origin through methylation: **Prader-Willi syndrome** (paternal 15q11-13 deletion or maternal **uniparental disomy**, hyperphagia with obesity, short stature, intellectual disability) mirrors **Angelman syndrome** (maternal deletion or paternal UPD, severe disability with ataxia, inappropriate laughter, seizures) at the same locus. **Uniparental disomy** (both homologues from one parent) unmasks imprinting or recessive mutations; Beckwith-Wiedemann (paternal 11p15 excess, macrosomia with Wilms risk) inverts the pattern. Methylation testing with FISH sorts deletions from disomy.", "Same chromosome, opposite parent lost: Prader-Willi eats, Angelman laughs. Both homologues from one parent is disomy."),
  step("**Trinucleotide repeats** expand across generations causing **anticipation** (earlier, severer disease): **fragile X** (CGG in FMR1, intellectual disability with macroorchidism and long face; premutations cause **primary ovarian insufficiency** and tremor ataxia syndrome), **myotonic dystrophy** (CTG in DMPK, hatchet face with cataracts, myotonia, cardiac block, congenital severe form), **Huntington disease** (CAG in HTT, chorea with dementia, paternal transmission expands most). Southern blot or PCR sizes repeats; premutation carriers need family counselling before expansion.", "Repeats growing each generation strike earlier: fragile X, myotonic dystrophy, Huntington. Fathers expand Huntington most."),
  step("**Mitochondrial inheritance** passes only through ova (sperm mitochondria discarded), so affected mothers transmit to all children while fathers transmit to none; **heteroplasmy** (mutant load varying by tissue) explains variable severity. **MELAS** (stroke like episodes with lactic acidosis) and **MERRF** (myoclonus with ragged red fibres) strike energy hungry brain and muscle; **Leber optic neuropathy** blinds young men sequentially (covered in neuro ophthalmology wave). Muscle biopsy with respiratory chain assays and mtDNA sequencing confirms; maternal relatives counselled.", "Mother to all children, father to none: mitochondrial. Mixed mutant loads vary the damage: heteroplasmy."),
  step("**Mosaicism** (postzygotic mutation, McCune-Albright with cafe au lait and precocious puberty, segmental neurofibromatosis) and **gonadal mosaicism** (phenotypically normal parent with multiple affected children, as in osteogenesis imperfecta) explain recurrence defying Mendelian ratios. Counselling computes empiric risks: imprinting needs parent of origin testing, repeats need sizing, mitochondria need maternal pedigree, mosaicism needs gonadal sampling debates. Pedigree with molecular testing replaces risk tables.", "Normal parents with several affected children suggest gonadal mosaicism. Pedigree plus molecules sets recurrence.", tbl(["Mechanism", "Example", "Test"], [["Imprinting", "Prader-Willi/Angelman", "Methylation, FISH"], ["Repeats", "Fragile X/Huntington", "Repeat sizing"], ["Mitochondrial", "MELAS/MERRF", "mtDNA, biopsy"], ["Disomy", "Beckwith-Wiedemann", "Microsatellites"]]))],
 ["Parent of origin decides imprinting", "Growing repeats strike earlier", "Mothers transmit mitochondria to all", "Mosaic gonads surprise pedigrees"],
 "Differential methylation marks gametes so only one parental allele transcribes; slippage expands repeats into toxic RNA or polyglutamine, and bottleneck segregation shuffles mutant mitochondria into tissues randomly.",
 ["Prader-Willi versus Angelman by eating and laughter", "Premutation versus full mutation by ovaries and ataxia", "Mitochondrial versus X linked by paternal transmission"],
 ["Methylation with FISH in hypotonic infants", "Repeat sizing with premutation counselling", "Muscle biopsy with mtDNA in stroke like youth"],
 [mcq("bk2-pat-361", "Hyperphagic obese short child with intellectual disability and paternal 15q deletion has what?", ["Angelman", "Prader-Willi syndrome from paternal imprint loss", "Down", "Fragile X"], 1, "Paternal expression lost at 15q11-13 drives hunger with hypotonia; maternal UPD mimics while Angelman inverts (maternal loss, laughter with ataxia). Methylation testing confirms.", ["Incorrect. Angelman laughs ataxic.", "Correct. Prader-Willi paternal.", "Incorrect. Chromosomes differ.", "Incorrect. Repeats differ."], "Paternal 15q lost, hunger gained: Prader-Willi."),
  mcq("bk2-pat-362", "Severe disability with ataxia and inappropriate laughter suggests Angelman; the molecular lesion is what?", ["Paternal deletion 15q", "Maternal 15q11-13 loss or paternal UPD silencing UBE3A", "Trisomy 21", "FMR1 expansion"], 1, "Maternal UBE3A alone expresses in neurons; paternal disomy doubles silenced copies while Prader-Willi mirrors paternally. Seizures with happy puppetry mark.", ["Incorrect. Paternal is Prader-Willi.", "Correct. Maternal loss Angelman.", "Incorrect. Counts differ.", "Incorrect. X linked differs."], "Laughing ataxic child: maternal 15q lost."),
  mcq("bk2-pat-363", "Macroorchidism with long face and intellectual disability in a boy suggests fragile X; premutation females risk what?", ["No risk", "Primary ovarian insufficiency with tremor ataxia in carrier males", "Huntington", "Myotonia"], 1, "CGG premutations (55 to 200) fail ovaries early and shake older males (FXTAS) while full mutations silence FMR1. Repeat sizing counsels families.", ["Incorrect. Ovaries fail early.", "Correct. Premutation ovaries and tremor.", "Incorrect. CAG differs.", "Incorrect. CTG differs."], "Fragile X carriers: ovaries fail, elders tremble."),
  mcq("bk2-pat-364", "Hatchet face with cataracts, myotonia and heart block suggests myotonic dystrophy; the repeat and risk are what?", ["CAG; maternal", "CTG in DMPK expanding, congenital severe with affected mothers", "CGG; paternal", "GAA; no risk"], 1, "Toxic RNA traps splicing factors multisystemically; congenital form (hypotonia with respiratory failure) follows large maternal expansions. Cardiac pacing watched.", ["Incorrect. Huntington is CAG.", "Correct. CTG myotonic.", "Incorrect. Fragile is CGG.", "Incorrect. Friedreich is GAA."], "Myotonia plus cataracts plus block: CTG."),
  mcq("bk2-pat-365", "Chorea with dementia worsening earlier in successive generations with paternal transmission is what?", ["Alzheimer", "Huntington CAG anticipation", "Parkinson", "Wilson"], 1, "Polyglutamine striatal loss starts with fidgets ending demented; predictive testing counsels before symptoms as no cure exists. Paternal meiosis expands most.", ["Incorrect. Cortical differs.", "Correct. Huntington CAG.", "Incorrect. Bradykinesia differs.", "Incorrect. Copper differs."], "Earlier chorea each generation: Huntington."),
  mcq("bk2-pat-366", "Stroke like episodes with lactic acidosis in a youth with maternal deafness and diabetes suggests what?", ["MELAS mitochondrial disease", "Stroke thrombotic", "MERRF only", "Encephalitis"], 1, "Maternal inheritance with heteroplasmic mtDNA (m.3243A>G commonest) strokes without vessels; arginine with coenzyme Q debates support. Thrombolysis never helps metabolic strokes.", ["Correct. MELAS maternal strokes.", "Incorrect. Vessels are clean.", "Incorrect. Myoclonus defines MERRF.", "Incorrect. CSF is calm."], "Metabolic strokes maternally: MELAS."),
  mcq("bk2-pat-367", "An affected father with mitochondrial disease has what recurrence risk to children?", ["50 percent", "Zero: paternal mitochondria are not transmitted", "100 percent", "25 percent"], 1, "Ova alone contribute mitochondria; all children of carrier mothers inherit (variable heteroplasmy) while fathers transmit none. Pedigree proves.", ["Incorrect. No paternal passage.", "Correct. Fathers transmit none.", "Incorrect. Mothers transmit all.", "Incorrect. Mendelian ratios mislead."], "Mitochondrial fathers risk none."),
  mcq("bk2-pat-368", "Macrosomia with Wilms tumour risk and paternal 11p15 excess is which overgrowth?", ["Weaver", "Beckwith-Wiedemann with imprinting excess", "Sotos", "Simpson"], 1, "Paternal duplication overgrows with hemihyperplasia, macroglossia and omphalocele; tumour surveillance (Wilms, hepatoblastoma) runs years. Methylation testing confirms.", ["Incorrect. Different genes.", "Correct. Beckwith-Wiedemann.", "Incorrect. NSD1 differs.", "Incorrect. GPC3 differs."], "Big baby Wilms risk: Beckwith-Wiedemann."),
  mcq("bk2-pat-369", "Phenotypically normal parents with two osteogenesis imperfecta children suggest what mechanism?", ["New mutation twice", "Gonadal mosaicism with empiric recurrence counselling", "Recessive always", "No risk"], 1, "Germline confined mutation recurs invisibly; dominant collagen defects repeat while somatic testing stays normal. Empiric figures replace zero risk.", ["Incorrect. Twice unlikely.", "Correct. Gonads mosaic.", "Incorrect. Dominant usually.", "Incorrect. Risk persists."], "Normal parents, twice affected: gonadal mosaic."),
  mcq("bk2-pat-370", "Uniparental disomy causes disease chiefly by which two routes?", ["Aneuploidy always", "Imprinting unmasking or recessive homozygosity", "No effect", "Triploidy"], 1, "Isodisomy doubles mutant recessives while heterodisomy skews imprints (maternal UPD15 Prader-Willi); microsatellites prove parentage. Counts stay diploid.", ["Incorrect. Diploid preserved.", "Correct. Imprint or unmask.", "Incorrect. Phenotypes prove.", "Incorrect. Sets differ."], "Disomy harms by imprint or unmasking.")]);

add("pat-haematopoiesis-marrow-failure", "Bone marrow failure: aplastic anaemia, red cell aplasia and pancytopenia", "marrow_failure_aplastic_pancytopenia_redcell", "Bone Marrow Failure: Aplastic Anaemia, Red Cell Aplasia and Pancytopenia",
 ["Aplastic anaemia causes and marrow", "Fanconi, PNH and inherited failures", "Red cell aplasia and parvovirus", "Pancytopenia differentials"],
 [step("**Aplastic anaemia** empties multipotent myeloid stem cells (fatty hypocellular marrow with pancytopenia and reticulocytopenia) after benzene, chloramphenicol, hepatitis, pregnancy or autoimmunity; severity grades by neutrophils, platelets and reticulocytes. Young patients with donors get **bone marrow transplant** (curative), others get **antithymocyte globulin with ciclosporin** (and eltrombopag debates); androgens bridge historically. Transfuse sparingly (alloimmunisation) with iron watched; MDS and PNH clones lurk in survivors.", "Empty fatty marrow with pancytopenia is aplastic: transplant the young, immune suppress the rest. Benzene and chloramphenicol warn."),
  step("**Inherited failures** declare early: **Fanconi anaemia** (DNA repair defect, cafe au lait with thumb and radial anomalies, microcephaly, chromosome breakage with DEB testing, leukaemia risk, BMT before malignancy), dyskeratosis congenita (nail dystrophy with leukoplakia, telomere short), Shwachman-Diamond (pancreatic insufficiency with neutropenia). **Paroxysmal nocturnal haemoglobinuria** (PIGA somatic clone, GPI anchor loss, morning haemoglobinuria with thrombosis and aplasia overlap, **eculizumab**, FLAER testing) bridges acquired and inherited; small PNH clones complicate half of aplastic cases.", "Thumb anomalies with marrow failure are Fanconi: breakage testing. Morning dark urine with clots is PNH: eculizumab."),
  step("**Pure red cell aplasia** (reticulocytopenia with absent erythroblasts, normal white cells and platelets) splits into **Diamond-Blackfan** (ribosomal, congenital with thumb and craniofacial anomalies, steroids then BMT) and acquired (thymoma resected, parvovirus B19 in haemolytics, anti EPO antibodies). **Parvovirus B19** (slapped cheek fifth disease, **aplastic crisis** in sickle and spherocytosis as giant pronormoblasts halt red cells, hydrops in pregnancy) is diagnosed by IgM or PCR; IVIG treats chronic infection in immunodeficiency. Myelophthisis (fibrosis, granulomas, metastases with teardrop cells) crowds out last.", "No reticulocytes with empty red precursors is red cell aplasia. Slapped cheek then sickle crisis is parvovirus B19."),
  step("**Pancytopenia differentials** organise by marrow: hypocellular (aplastic, Fanconi, PNH, hypoplastic MDS), hypercellular with ineffective production (megaloblastic B12 and folate, MDS with blasts and dysplasia, AML), infiltrative (myelofibrosis with tear drops and massive spleen, tuberculosis, lymphoma, metastatic prostate), peripheral destruction (hypersplenism, sepsis, SLE). **Reticulocyte count** first separates production failure (low) from destruction or loss (high); marrow biopsy with cytogenetics then stages. B12 and folate correct before marrow blamed.", "Pancytopenia with low reticulocytes is production failure: biopsy the marrow. High reticulocytes mean destruction or bleed.", tbl(["Failure", "Marrow", "Fix"], [["Aplastic", "Empty fatty", "BMT or ATG"], ["Fanconi", "Breakage", "BMT early"], ["PNH", "Clone GPI lost", "Eculizumab"], ["PRCA", "Red absent", "Steroids or IVIG"]]))],
 ["Empty marrow pancytopenia: aplastic", "Breakage plus thumbs: Fanconi", "Morning haemoglobinuria plus clots: PNH", "No reticulocytes: red cell aplasia"],
 "Autoreactive T cells apoptose stem cells into fat while Fanconi repair failure breaks chromosomes; PIGA clones escape immune attack expanding GPI bare cells that complement lyses intravascularly, and parvovirus NS1 arrests erythropoiesis at pronormoblasts.",
 ["Aplastic versus MDS by blasts and dysplasia", "Fanconi versus acquired aplastic by anomalies and breakage", "PRCA versus myelophthisis by white cells and tear drops"],
 ["Reticulocytes with marrow biopsy and cytogenetics", "DEB breakage with telomere length in inherited failure", "FLAER with Ham test in haemoglobinuria"],
 [mcq("bk2-pat-371", "Fatty hypocellular marrow with pancytopenia and reticulocytopenia after benzene exposure is what?", ["MDS", "Aplastic anaemia needing BMT young or ATG with ciclosporin", "Leukaemia", "Myelofibrosis"], 1, "Stem cell emptying without blasts or fibrosis defines; severity counts gate transplant versus immunosuppression while clones watched. MDS shows dysplasia with blasts.", ["Incorrect. MDS is dysplastic.", "Correct. Aplastic empty marrow.", "Incorrect. Blasts absent.", "Incorrect. Fibrosis absent."], "Empty fatty marrow: aplastic."),
  mcq("bk2-pat-372", "Cafe au lait with thumb anomalies and marrow failure in a child suggests Fanconi; confirm how?", ["Marrow alone", "Chromosome breakage with DEB testing", "Hb electrophoresis", "No test"], 1, "DNA repair failure shatters chromosomes under crosslinkers; BMT precedes leukaemia while androgens bridge. Electrophoresis suits haemoglobinopathies.", ["Incorrect. Breakage proves.", "Correct. DEB breakage Fanconi.", "Incorrect. Globins differ.", "Incorrect. Test exists."], "Thumbs plus failure: break chromosomes."),
  mcq("bk2-pat-373", "Morning haemoglobinuria with venous thrombosis and aplasia overlap is PNH; therapy is what?", ["Steroids", "Eculizumab with terminal complement blockade and vaccines", "Splenectomy", "Iron only"], 1, "GPI anchor loss invites MAC lysis intravascularly; anti C5 halves thrombosis with marrow failure watched. Splenectomy suits spherocytosis instead.", ["Incorrect. Complement drives.", "Correct. Eculizumab PNH.", "Incorrect. Spleen is normal.", "Incorrect. Iron never stops lysis."], "Dark mornings plus clots: PNH."),
  mcq("bk2-pat-374", "FLAER negativity in PNH testing means what?", ["Normal cells", "GPI anchor loss marking the PNH clone size", "No clone", "Leukaemia"], 1, "Fluorescent aerolysin binds GPI directly; negative populations size the clone guiding eculizumab with thrombosis watched. Ham test acidifies historically.", ["Incorrect. Loss marks clone.", "Correct. FLAER negative clone.", "Incorrect. Clone is present.", "Incorrect. Blasts absent."], "FLAER negative: GPI gone, PNH."),
  mcq("bk2-pat-375", "Absent erythroblasts with normal white cells and platelets plus thymoma is which entity and treated how?", ["Aplastic anaemia", "Pure red cell aplasia: thymectomy with steroids or ciclosporin", "MDS", "Myeloma"], 1, "Red lineage alone fails (reticulocytopenia stark); thymoma removal with immunosuppression restores while parvovirus PCR excludes B19. MDS dysplasias multilineage.", ["Incorrect. Lineages spared.", "Correct. PRCA, resect thymoma.", "Incorrect. Dysplasia absent.", "Incorrect. Plasma cells differ."], "Reds alone absent with thymoma: PRCA."),
  mcq("bk2-pat-376", "Slapped cheek rash then aplastic crisis in sickle cell disease is parvovirus B19 acting how?", ["New infection always", "Giant pronormoblast arrest halting red cells in shortened survival", "Iron deficiency", "Sequestration"], 1, "NS1 kills erythroid precursors; normal red cell lifespan tolerates while sickle turnover crashes. IgM or PCR confirms; IVIG treats chronic immunodeficient infection.", ["Incorrect. Arrest, not novelty.", "Correct. B19 crisis sickle.", "Incorrect. Reticulocytes absent.", "Incorrect. Spleen differs."], "Cheek slap then sickle crash: B19."),
  mcq("bk2-pat-377", "Hydrops fetalis after maternal fifth disease exposure is parvovirus acting how and managed how?", ["No risk", "Fetal anaemia with high output failure; intrauterine transfusion watched", "Teratogenic limbs", "No action"], 1, "Fetal erythropoiesis arrests oedematously; MCA Doppler peaks gate transfusion while IgM confirms. Limbs form normally.", ["Incorrect. Anaemia drowns fetus.", "Correct. Hydrops, transfuse fetus.", "Incorrect. No malformation.", "Incorrect. Surveillance saves."], "Fifth disease pregnancy: watch fetal anaemia."),
  mcq("bk2-pat-378", "Teardrop cells with massive spleen and dry marrow tap suggest myelofibrosis; the mutation is usually what?", ["BCR-ABL", "JAK2 with leukoerythroblastosis", "PML-RARA", "MYC"], 1, "Clonal megakaryocytes fibrose marrow displacing haematopoiesis to spleen; ruxolitinib shrinks while transplant cures young. CML basophils with BCR-ABL differ.", ["Incorrect. CML differs.", "Correct. JAK2 fibroses.", "Incorrect. APL differs.", "Incorrect. Burkitt differs."], "Tear drops massive spleen: JAK2 fibrosis."),
  mcq("bk2-pat-379", "Pancytopenia with high reticulocytes and splenomegaly suggests peripheral destruction; first distinction is what?", ["Marrow always", "Reticulocytes separating destruction or loss from production failure", "No test", "Transfuse always"], 1, "High counts prove marrow working against hypersplenism, sepsis or bleed; low counts demand biopsy. Smear with Coombs refines.", ["Incorrect. Reticulocytes first.", "Correct. High means working marrow.", "Incorrect. Smear guides.", "Incorrect. Cause first."], "High reticulocytes: marrow works, periphery destroys."),
  mcq("bk2-pat-380", "Diamond-Blackfan anaemia with thumb anomalies in infancy is treated first how?", ["BMT always", "Steroids with transfusion support, BMT for non responders", "No treatment", "Splenectomy"], 1, "Ribosomal haploinsufficiency arrests red precursors steroid responsively; iron chelation follows transfusions while BMT cures refractory. Splenectomy suits spherocytosis.", ["Incorrect. Steroids first.", "Correct. Steroids DBA.", "Incorrect. Anaemia threatens.", "Incorrect. Spleen is normal."], "Infant red failure thumbs: steroids first.")]);

add("pat-myocardial-pericardial", "Myocarditis, cardiomyopathies and pericardial disease", "myocarditis_cardiomyopathy_pericardial_disease", "Myocarditis, Cardiomyopathies and Pericardial Disease",
 ["Myocarditis causes and Dallas", "Dilated and hypertrophic CMP", "Restrictive, ARVC and stress CMP", "Pericarditis, tamponade and constriction"],
 [step("**Myocarditis** (viral Coxsackie B commonest, parvovirus B19, Chagas with apical aneurysm, diphtheria, hypersensitivity drugs, **giant cell** fulminant in young with VT) presents with chest pain, heart failure or arrhythmia after viral prodrome; troponin with MRI Lake Louise criteria supports while **Dallas criteria** (endomyocardial biopsy lymphocytic infiltrate with myocyte necrosis) confirms. Most viral cases rest into recovery with heart failure therapy; giant cell needs combined immunosuppression with transplant listing, fulminant cases need mechanical support. Athletes rest months.", "Chest pain with failure after viral flu is myocarditis: rest, biopsy Dallas confirms. Giant cell VT storms need transplant listing."),
  step("**Dilated cardiomyopathy** (alcohol, peripartum, haemochromatosis, anthracyclines, TTN truncations, tachycardia induced) dilates thin walls into systolic failure treated as HFrEF with devices; **hypertrophic cardiomyopathy** (autosomal dominant **MYH7 and MYBPC3**, **asymmetric septal hypertrophy** with SAM and dynamic outflow murmur easing on squatting, myocyte disarray) kills young athletes suddenly. HCM management is beta blockers, **septal myectomy or alcohol ablation** for obstruction, ICD by risk (family death, unexplained syncope, massive thickness, NSVT), endocarditis prophylaxis debated, strenuous sport avoided.", "Thin dilated failure is DCM. Thick septum with dynamic murmur is HCM: beta block, myectomy, ICD by risk."),
  step("**Restrictive cardiomyopathy** (amyloid with low voltage plus thick walls, sarcoid with AV block, haemochromatosis, endomyocardial fibrosis) stiffens diastolic filling with **Kussmaul sign** (JVP rising on inspiration) shared with constriction; **arrhythmogenic RV cardiomyopathy** (**plakoglobin desmosomes**, epsilon waves with T inversions V1 to V3, VT of LBBB morphology, fibrofatty replacement) restricts athletes with ICD. **Stress Takotsubo** (postmenopausal grief, apical ballooning with clean coronaries) recovers; **LV noncompaction** trabeculates with clots and failure.", "Thick walls with tiny voltage are amyloid restrictive. Epsilon waves with LBBB VT are ARVC: ICD, no sport."),
  step("**Acute pericarditis** (viral idiopathic, uremic, post MI Dressler, TB, purulent Staph) gives pleuritic pain easing leaning forward with **diffuse concave ST elevation and PR depression**; treatment is **NSAIDs plus colchicine** (aspirin post MI), steroids only in autoimmune or refractory. **Tamponade** (Beck triad hypotension with muffled sounds and JVD, **pulsus paradoxus**, electrical alternans, diastolic chamber collapse) needs urgent **pericardiocentesis**; **constriction** (calcified rigid sac, **pericardial knock**, equalised diastolic pressures, septal bounce) needs **pericardiectomy**.", "Lean forward relief with diffuse ST elevation is pericarditis: NSAID plus colchicine. Muffled shock with paradoxus is tamponade: needle now.", tbl(["Disease", "Sign", "Fix"], [["Myocarditis", "Postviral failure", "Rest, Dallas"], ["HCM", "Dynamic murmur", "Beta block, myectomy"], ["Tamponade", "Paradoxus", "Pericardiocentesis"], ["Constriction", "Knock, Kussmaul", "Pericardiectomy"]]))],
 ["Postviral failure or arrhythmia: myocarditis", "Dynamic murmur easing squat: HCM", "Low voltage thick walls: amyloid", "Paradoxus muffled shock: tamponade"],
 "Lymphocytic killing hollows myocytes into dilated thin sacs while sarcomere mutations thicken septa into obstructing muscle; fibrinous exudates glue pericardial layers that calcify into rigid boxes equalising diastolic pressures.",
 ["Myocarditis versus MI by age, prodrome and coronaries", "HCM versus athlete heart by disarray and SAM", "Tamponade versus constriction by collapse versus knock"],
 ["Troponin with cardiac MRI in postviral failure", "Echo with septal thickness and SAM in dynamic murmurs", "Echo diastolic collapse with equalised pressures in pericardial shock"],
 [mcq("bk2-pat-381", "Chest pain with heart failure 2 weeks after viral flu in a young adult is likely myocarditis; confirm how?", ["Coronary angio always", "Cardiac MRI with Dallas biopsy criteria in selected cases", "No test", "D-dimer"], 1, "Lake Louise oedema with necrosis patterns supports while biopsy proves lymphocytic killing; coronaries stay clean in youth. Rest with heart failure therapy recovers most.", ["Incorrect. Youth coronaries clean.", "Correct. MRI plus Dallas.", "Incorrect. Tests stage.", "Incorrect. Clots differ."], "Postviral failure: MRI, Dallas confirms."),
  mcq("bk2-pat-382", "VT storm with fulminant failure in a young adult suggests giant cell myocarditis; management is what?", ["Reassurance", "Combined immunosuppression with early transplant listing", "Antibiotics", "Statins"], 1, "Multinucleated giant cells necrotise rapidly fatal without transplant; mechanical support bridges while biopsy proves. Viral lymphocytic rests instead.", ["Incorrect. Fulminance kills.", "Correct. Suppress plus list.", "Incorrect. No bacteria.", "Incorrect. Lipids uninvolved."], "Giant cell VT storm: list for transplant."),
  mcq("bk2-pat-383", "Asymmetric septal hypertrophy with dynamic murmur easing on squatting is HCM; the genes and sudden death plan are what?", ["TTN; no plan", "MYH7 or MYBPC3 with ICD by risk factors", "LDLR; statins", "No genes"], 1, "Sarcomere disarray obstructs dynamically with myectomy or ablation for gradients; family death, syncope, massive thickness and NSVT gate ICD. Sport restriction saves.", ["Incorrect. DCM gene differs.", "Correct. Sarcomere plus ICD.", "Incorrect. Lipids differ.", "Incorrect. Dominant families."], "Dynamic septal murmur: sarcomere, ICD risk."),
  mcq("bk2-pat-384", "Thick ventricular walls with tiny ECG voltage and periorbital purpura suggest cardiac amyloid; confirm how?", ["Echo alone", "Fat pad or cardiac biopsy with mass spectrometry typing AL versus TTR", "No test", "Creatine kinase"], 1, "Infiltrative stiffness with conduction disease types by precursor (light chains versus transthyretin) as tafamidis suits TTR while chemo suits AL. Voltage wall mismatch flags.", ["Incorrect. Typing treats.", "Correct. Biopsy types amyloid.", "Incorrect. Tests exist.", "Incorrect. Muscle differs."], "Thick walls tiny voltage: biopsy types amyloid."),
  mcq("bk2-pat-385", "Epsilon waves with T inversions V1 to V3 and LBBB VT in a young athlete are ARVC; management is what?", ["Continue sport", "Sport restriction with ICD and family screening", "Ablation cures", "No action"], 1, "Desmosomal fibrofatty replacement arrhythmias fatally on exertion; ICD with beta blockers protects while relatives screen. Ablation palliates only.", ["Incorrect. Exertion kills.", "Correct. ICD, no sport.", "Incorrect. Palliation only.", "Incorrect. Family at stake."], "Epsilon LBBB VT: ARVC, ICD."),
  mcq("bk2-pat-386", "Apical ballooning with clean coronaries after bereavement in an older woman is Takotsubo; course is what?", ["Always fatal", "Recovery with supportive care and trigger counselling", "Bypass needed", "No recovery"], 1, "Catecholamine stunning mimics MI with modest troponin; function returns weeks while recurrence watched. Coronaries prove clean.", ["Incorrect. Recovery rules.", "Correct. Broken heart recovers.", "Incorrect. No plaque.", "Incorrect. Function returns."], "Grief balloon apex: Takotsubo recovers."),
  mcq("bk2-pat-387", "Pleuritic pain easing leaning forward with diffuse concave ST elevation is pericarditis; therapy is what?", ["Heparin", "NSAIDs plus colchicine (aspirin post MI)", "Steroids first", "No treatment"], 1, "Inflamed layers rub ECG diffusely without reciprocal change; colchicine halves recurrence while steroids reserve autoimmune. Post MI uses aspirin.", ["Incorrect. Bleed risks.", "Correct. NSAID plus colchicine.", "Incorrect. Reserve steroids.", "Incorrect. Recurrence threatens."], "Lean forward ST elevation: colchicine duo."),
  mcq("bk2-pat-388", "Hypotension with muffled sounds, JVD and pulsus paradoxus after cardiac procedure is tamponade; next step is what?", ["Fluids only", "Urgent pericardiocentesis with echo guidance", "Diuretics", "Observation"], 1, "Diastolic collapse strangulates filling; needle drainage restores while fluids bridge. Diuretics empty further fatally.", ["Incorrect. Filling is strangled.", "Correct. Needle the sac now.", "Incorrect. Diuretics kill.", "Incorrect. Minutes matter."], "Beck triad post procedure: needle."),
  mcq("bk2-pat-389", "Pericardial knock with Kussmaul sign and equalised diastolic pressures after TB suggests constriction; cure is what?", ["Pericardiocentesis", "Surgical pericardiectomy stripping the rigid sac", "Diuretics lifelong", "Steroids alone"], 1, "Calcified box freezes filling with septal bounce; stripping restores while fluids and diuretics bridge. Taps find no fluid.", ["Incorrect. No fluid to tap.", "Correct. Strip the box.", "Incorrect. Palliation only.", "Incorrect. Scar is mechanical."], "Knock plus Kussmaul: strip pericardium."),
  mcq("bk2-pat-390", "Chagas chronic cardiomyopathy with apical aneurysm and megaoesophagus is managed how?", ["Cure with drugs", "Heart failure with devices, arrhythmia watched; benznidazole early only", "No care", "Transplant always"], 1, "Trypanosomal fibrosis aneurysms apex with RBBB; antiparasitics help acute while chronic supports with ICD debates. Mega disease surgeons manage.", ["Incorrect. Fibrosis persists.", "Correct. Support chronic Chagas.", "Incorrect. Failure needs care.", "Incorrect. Selected listing."], "Chagas heart: support the scar.")]);

add("pat-intestine", "Intestinal pathology: malabsorption, IBD, polyps and Hirschsprung", "intestinal_malabsorption_ibd_polyps_hirschsprung", "Intestinal Pathology: Malabsorption, IBD, Polyps and Hirschsprung",
 ["Coeliac and Whipple", "Crohn versus ulcerative colitis", "Polyps and cancer pathways", "Hirschsprung and ischaemia"],
 [step("**Coeliac disease** (HLA-DQ2 and DQ8, gluten gliadin, **tTG IgA** with total IgA checked, **villous atrophy** with intraepithelial lymphocytes) causes iron deficiency, diarrhoea and failure to thrive with **dermatitis herpetiformis** (itchy extensor vesicles, dapsone) and **refractory sprue with enteropathy lymphoma** risk; **gluten free diet** heals with serology followed. **Whipple disease** (Tropheryma whipplei, **PAS positive** foamy macrophages, arthralgia with diarrhoea and nodes, CNS oculomasticatory) needs prolonged **ceftriaxone then cotrimoxazole**; SIBO (blind loops, B12 low with folate high, breath tests, rifaximin) and disaccharidase deficiency complete malabsorption.", "Villous flattening with tTG positivity is coeliac: gluten free for life. PAS foamy macrophages with joints are Whipple: long antibiotics."),
  step("**Crohn disease** (mouth to anus, **skip lesions** with **creeping fat** and strictures, **transmural** with **noncaseating granulomas**, cobblestoning, fistulas, smoking worsens) differs from **ulcerative colitis** (rectum upward continuous, **crypt abscesses** with goblet depletion, toxic megacolon, smoking protects, **primary sclerosing cholangitis** associates). UC bleeds superficially; Crohn obstructs and fistulises. Treatment steps mesalazine (UC), steroids, thiopurines, **anti TNF and vedolizumab or ustekinumab**; surgery colectomises UC curatively while Crohn recurs. Colonoscopy with biopsies sorts.", "Skip transmural fistulising is Crohn; continuous rectal bleeding is UC. Smoking harms Crohn, shields UC."),
  step("**Colorectal polyps** sort malignant potential: hyperplastic (serrated benign, distal), **adenomas** (tubular, tubulovillous, villous with worst risk, size and high grade dysplasia drive), sessile serrated (BRAF, right sided, interval cancers), hamartomatous (juvenile, Peutz-Jeghers STK11 with mucocutaneous pigment, Cowden PTEN). **APC pathway** (chromosomal instability, FAP with hundreds of polyps and desmoids, prophylactic colectomy) differs from **microsatellite instability** (**HNPCC Lynch** with MSH2 and MLH1, right sided with endometrial and ovarian tumours, Amsterdam criteria, aspirin debates). Snare with surveillance intervals prevents.", "Villous large polyps threaten most. Hundreds of polyps with desmoids are FAP: colectomy prevents."),
  step("**Hirschsprung disease** (aganglionic distal bowel from failed neural crest migration, **RET** mutations, Down association, male predominance) presents with delayed meconium, bilious vomiting and enterocolitis; **suction biopsy** (absent ganglia with hypertrophic nerves, calretinin lost) confirms with transition zone on contrast enema. Treatment is pull through (Swenson, Soave, Duhamel) resecting to ganglionic bowel. **Mesenteric ischaemia** (AF emboli with pain out of proportion and lactic acidosis, watershed ischaemic colitis) and Ogilvie pseudo obstruction complete emergencies.", "No meconium in 48 hours with transition zone is Hirschsprung: biopsy then pull through. Pain out of proportion is mesenteric ischaemia.", tbl(["Bowel", "Pattern", "Fix"], [["Crohn", "Skip transmural", "Anti TNF"], ["UC", "Continuous rectal", "Colectomy cures"], ["FAP", "Hundreds APC", "Prophylactic colectomy"], ["Hirschsprung", "Aganglionic", "Pull through"]]))],
 ["tTG plus flat villi: gluten free", "Skip fistulising is Crohn; bloody continuous is UC", "Villous large polyps threaten; FAP colectomises", "No meconium plus transition: Hirschsprung"],
 "Gliadin deamidation triggers tTG autoimmunity flattening villi while NOD2 mishandles flora granulomatising transmurally; APC loss unleashes Wnt adenomas that mismatch repair failure hypermutates, and aganglionic bowel spasms functionally obstructing.",
 ["Crohn versus UC by skip, depth and smoke", "Adenoma versus hyperplastic by dysplasia and serration", "Hirschsprung versus meconium ileus by biopsy and CF"],
 ["tTG IgA with duodenal biopsy on gluten", "Colonoscopy with segmental biopsies in chronic diarrhoea", "Suction biopsy with contrast enema in delayed meconium"],
 [mcq("bk2-pat-391", "Iron deficiency with tTG IgA positivity and villous atrophy is coeliac; the diet and follow up are what?", ["Low fat", "Strict gluten free diet with serology and lymphoma watched", "High gluten", "No diet"], 1, "Gliadin withdrawal heals mucosa with antibodies falling; refractory disease biopsies for lymphoma while dapsone calms herpetiformis. Oats debated pure.", ["Incorrect. Fat is fine.", "Correct. Gluten free life.", "Incorrect. Gluten harms.", "Incorrect. Diet is therapy."], "tTG flat villi: gluten free."),
  mcq("bk2-pat-392", "PAS positive foamy macrophages with arthralgia and diarrhoea suggest Whipple; therapy is what?", ["Short amoxicillin", "Prolonged ceftriaxone then cotrimoxazole for a year or more", "No treatment", "Steroids"], 1, "Tropheryma hides in macrophages relapsing in CNS without long cover; oculomasticatory movements flag neuro spread. Brief courses relapse.", ["Incorrect. Relapse follows short.", "Correct. Year long Whipple cover.", "Incorrect. CNS threatens.", "Incorrect. Steroids worsen."], "PAS macrophages plus joints: long Whipple drugs."),
  mcq("bk2-pat-393", "Skip lesions with creeping fat, strictures and fistulas that worsen with smoking are Crohn; maintenance is what?", ["Mesalazine cures", "Thiopurines with anti TNF, vedolizumab or ustekinumab stepwise", "Surgery cures", "No therapy"], 1, "Transmural disease recurs after resections; biologics heal mucosa with smoking cessation while surgery strictures complications. Mesalazine suits UC better.", ["Incorrect. Crohn recurs post op.", "Correct. Biologic stepwise Crohn.", "Incorrect. Surgery palliates.", "Incorrect. Fistulas need therapy."], "Skip fistulising smoker: Crohn biologics."),
  mcq("bk2-pat-394", "Continuous rectal bleeding with crypt abscesses and PSC association is UC; surgery does what?", ["Never operates", "Colectomy cures colonic disease with pouch options", "Worsens always", "No role"], 1, "Mucosal disease confined to colon removed cures bowel (extraintestinal PSC persists); toxic megacolon forces urgent colectomy. Crohn surgery recurs.", ["Incorrect. Colectomy cures UC bowel.", "Correct. Colectomy cures.", "Incorrect. Megacolon forces.", "Incorrect. Pouches restore."], "Continuous bloody UC: colectomy cures."),
  mcq("bk2-pat-395", "Toxic megacolon with transverse dilation over 6 cm in UC is managed how?", ["Continue mesalazine", "Urgent surgical colectomy with steroids and fluids bridging", "Discharge", "Laxatives"], 1, "Transmural necrosis perforates fatally; daily films with surgical threshold save while cyclosporine debates bridge. Distension with toxicity alarms.", ["Incorrect. Perforation looms.", "Correct. Colectomy toxic mega.", "Incorrect. Admission mandatory.", "Incorrect. Laxatives perforate."], "Dilated toxic colon: resect urgently."),
  mcq("bk2-pat-396", "Hundreds of adenomas with desmoid tumours and APC mutation is FAP; prevention is what?", ["Surveillance only", "Prophylactic colectomy with rectal and duodenal watched", "No action", "Aspirin alone"], 1, "Hundred percent cancer by midlife without removal; pouch with duodenal ampulla surveillance follows. Attenuated forms scope intensively.", ["Incorrect. Cancer is certain.", "Correct. Colectomy prevents.", "Incorrect. Polyps guarantee.", "Incorrect. Aspirin adjuncts."], "Hundreds APC polyps: colectomy."),
  mcq("bk2-pat-397", "Right sided colon cancer with endometrial cancer and MSH2 loss suggests Lynch; management includes what?", ["No screening", "Amsterdam guided intensive colonoscopy with gynaecologic surveillance and aspirin debates", "Colectomy always", "No family risk"], 1, "Mismatch repair failure hypermutates tumours (MSI high, immunotherapy responsive); family cascades test while hysterectomy completes childbearing. Bethesda guides testing.", ["Incorrect. Families at stake.", "Correct. Lynch intensive watch.", "Incorrect. Segmental suffices often.", "Incorrect. Dominant inheritance."], "Right plus womb cancers: Lynch watch."),
  mcq("bk2-pat-398", "Delayed meconium beyond 48 hours with bilious vomiting and transition zone is Hirschsprung; confirm how?", ["Anorectal manometry only", "Suction biopsy showing aganglionosis with hypertrophic nerves", "No test", "Laxatives trial"], 1, "Absent ganglia with calretinin loss proves; contrast maps transition while pull through resects to normal bowel. Meconium ileus (CF) differs radiologically.", ["Incorrect. Biopsy proves.", "Correct. Biopsy aganglionic.", "Incorrect. Tests exist.", "Incorrect. Obstruction threatens."], "No meconium transition: biopsy."),
  mcq("bk2-pat-399", "Atrial fibrillation with pain out of proportion, lactic acidosis and bloody stools is mesenteric ischaemia; next step is what?", ["Discharge", "Urgent CT angiography with embolectomy or revascularisation", "Antacids", "Colonoscopy"], 1, "Embolic SMA occlusion infarcts transmurally within hours; lactate with leukocytosis alarms while papaverine debates follow. Scope delays fatally.", ["Incorrect. Bowel dies hourly.", "Correct. CTA then revascularise.", "Incorrect. Ischaemia, not acid.", "Incorrect. Insufflation harms."], "AF pain disproportionate: CTA mesenteric."),
  mcq("bk2-pat-400", "Peutz-Jeghers polyps with mucocutaneous pigmentation and STK11 mutation risk which cancers and watched how?", ["No risk", "GI with breast, ovarian and testicular tumours under surveillance", "Skin only", "No follow up"], 1, "Hamartomas intussuscept while STK11 malignifies widely; endoscopy with breast and pelvic screening runs lifelong. Pigment lips flag.", ["Incorrect. Cancers multiply.", "Correct. STK11 wide watch.", "Incorrect. Viscera threaten.", "Incorrect. Lifelong scopes."], "Pigmented lips polyps: STK11 watch.")]);

add("pat-metabolic-liver-tumours", "Metabolic liver disease and hepatic tumours", "metabolic_liver_hemochromatosis_wilson_hcc", "Metabolic Liver Disease and Hepatic Tumours",
 ["NAFLD, alcohol and haemochromatosis", "Wilson, A1AT and cholestasis", "HCC diagnosis and Milan", "Cholangiocarcinoma and benign lesions"],
 [step("**Non alcoholic fatty liver** (insulin resistance, ballooning with lobular inflammation grading NASH activity) and **alcoholic liver disease** (central **Mallory hyaline** with neutrophilic satellitosis, chicken wire fibrosis, AST double ALT) both march steatosis to cirrhosis; abstinence with weight loss reverses early stages. **Hereditary haemochromatosis** (**C282Y** HFE, **bronze diabetes** with arthropathy of second and third MCPs, hypogonadism, cardiomyopathy, ferritin with high transferrin saturation, hepatic iron index) is treated with **phlebotomy**; secondary overload (thalassaemia transfusions) needs chelation. Fibroscan stages all.", "AST double ALT with Mallory is alcoholic. Bronze skin with diabetes and MCP pain is haemochromatosis: bleed it."),
  step("**Wilson disease** (ATP7B copper excretion failure, **Kayser-Fleischer rings**, low ceruloplasmin, high urinary copper, Coombs negative haemolysis with parkinsonism and dysarthria in youth) is treated with **penicillamine or trientine** (zinc blocks absorption, transplant fulminant); siblings screen. **Alpha 1 antitrypsin deficiency** (PiZZ, **PAS diastase resistant globules**, neonatal cholestasis, early panacinar emphysema, panniculitis) is managed supportively with augmentation debates. **Primary biliary cholangitis** (middle aged women, **anti mitochondrial M2**, pruritus with xanthelasma, ursodiol) differs from PSC (men, IBD, beading, cholangiocarcinoma risk).", "Young parkinsonism with brown corneal rings is Wilson: chelate copper. PASD globules with early emphysema are A1AT."),
  step("**Hepatocellular carcinoma** (HBV, HCV cirrhosis, alcohol, aflatoxin, **rising AFP**) is diagnosed radiologically: **arterial enhancement with portal venous washout** on triple phase CT or MRI (LI-RADS) with threshold growth; biopsy reserved for atypical lesions. **Milan criteria** (single under 5 cm or three under 3 cm, no vascular invasion or spread) gate transplant; resection suits noncirrhotic or preserved function, ablation bridges small lesions, **sorafenib or lenvatinib** with immunotherapy palliates advanced. Six monthly ultrasound with AFP surveils cirrhosis.", "Arterial blush washing out venously is HCC: Milan gates transplant. Cirrhosis images twice yearly."),
  step("**Cholangiocarcinoma** (PSC, **Clonorchis**, choledochal cysts, Thorotrast history, **CA19-9** with painless progressive jaundice and pruritus) is staged by Bismuth-Corlette hilar extent; resection with Roux-en-Y or transplant protocols suit selected hilar disease while stenting palliates. **Benign lesions** (haemangioma with peripheral nodular enhancement, **FNH** with central scar, adenoma with bleeding risk in OCP users needing resection) spare surgery mostly. Klatskin hilar tumours obstruct early; intrahepatic masses mimic HCC without washout.", "Painless progressive jaundice with CA19-9 is cholangiocarcinoma. Central scar is FNH: observe.", tbl(["Liver", "Marker", "Fix"], [["Haemochromatosis", "C282Y, iron", "Phlebotomy"], ["Wilson", "Low ceruloplasmin", "Penicillamine"], ["HCC", "AFP, washout", "Milan transplant"], ["Cholangio", "CA19-9", "Resect or stent"]]))],
 ["Bronze diabetes MCP pain: bleed", "Young parkinsonism brown rings: chelate", "Arterial blush venous washout: HCC", "Painless progressive jaundice: cholangio"],
 "Iron catalyses oxidative fibrosis while copper poisons basal ganglia mitochondria; HBV integrates oncogenically as cirrhotic nodules dysplasias into arterialised HCC, and chronic biliary inflammation metaplases ducts into desmoplastic adenocarcinoma.",
 ["Alcoholic versus NASH by AST ALT and hyaline", "PBC versus PSC by sex, antibodies and beading", "HCC versus cholangio by washout and CA19-9"],
 ["Ferritin with transferrin saturation and HFE", "Ceruloplasmin with urinary copper and slit lamp", "Triple phase CT or MRI with AFP in cirrhosis"],
 [mcq("bk2-pat-401", "Bronze skin with diabetes, MCP arthropathy and high transferrin saturation is haemochromatosis; therapy is what?", ["Chelation always", "Regular phlebotomy with family screening", "Steroids", "No treatment"], 1, "C282Y iron loads parenchymally (liver, pancreas, joints, heart); venesection depletes with ferritin watched while arthropathy persists. Transfusional overload chelates instead.", ["Incorrect. Primary bleeds.", "Correct. Phlebotomy bronze.", "Incorrect. Inflammation absent.", "Incorrect. Organs fail untreated."], "Bronze diabetes joints: bleed."),
  mcq("bk2-pat-402", "AST double ALT with Mallory hyaline and chicken wire fibrosis suggests alcoholic hepatitis; the discriminator from NASH is what?", ["No difference", "Neutrophilic satellitosis with AST 2x ALT and drinking history", "Viral serology", "Autoantibodies"], 1, "Alcoholic foamy degeneration centres with hyaline while NASH balloons diffusely; Maddrey discriminant with steroids debates severe cases. Abstinence reverses both early.", ["Incorrect. Patterns differ.", "Correct. Satellitosis AST double.", "Incorrect. Serology negative.", "Incorrect. ANA differs."], "AST double hyaline: alcohol."),
  mcq("bk2-pat-403", "Young parkinsonism with Kayser-Fleischer rings and low ceruloplasmin is Wilson; treatment and family step are what?", ["Levodopa only", "Penicillamine or trientine with sibling screening", "No treatment", "Transplant always"], 1, "Copper chelation with zinc blockade decoppers while diet restricts; fulminant haemolysis transplants urgently. Siblings test presymptomatically.", ["Incorrect. Copper, not dopamine.", "Correct. Chelate, screen sibs.", "Incorrect. Brain degrades.", "Incorrect. Fulminant only."], "Brown rings young parkinsonism: chelate."),
  mcq("bk2-pat-404", "PAS diastase resistant globules with neonatal cholestasis and early emphysema are A1AT; the allele and advice are what?", ["PiMM; no advice", "PiZZ with smoking cessation and augmentation debates", "No allele", "Surgery"], 1, "Misfolded polymers injure liver while lung lacks protection; cessation slows while family tests. Panniculitis flags variants.", ["Incorrect. Normal allele protects.", "Correct. PiZZ, stop smoking.", "Incorrect. Genetics define.", "Incorrect. No resection."], "PASD globules early emphysema: PiZZ."),
  mcq("bk2-pat-405", "Middle aged woman with pruritus, xanthelasma and anti mitochondrial M2 positivity has what and treated how?", ["PSC; transplant", "Primary biliary cholangitis with ursodiol", "Gallstones; surgery", "Hepatitis C"], 1, "Granulomatous bile duct loss cholestases chronically; ursodiol slows with transplant listing late while PSC (men, beading) differs. Statins never treat.", ["Incorrect. PSC is male beaded.", "Correct. PBC M2, ursodiol.", "Incorrect. Ducts, not stones.", "Incorrect. Serology differs."], "Itchy M2 woman: PBC."),
  mcq("bk2-pat-406", "Cirrhotic nodule with arterial enhancement and portal venous washout is HCC; transplant gating uses what?", ["No criteria", "Milan criteria without vascular invasion or spread", "Size only", "Age only"], 1, "Single under 5 or three under 3 cm with clean vessels transplants; resection suits preserved function while systemic therapy palliates beyond. LI-RADS standardises.", ["Incorrect. Criteria gate organs.", "Correct. Milan HCC.", "Incorrect. Number counts too.", "Incorrect. Biology, not age."], "Washout nodule: Milan decides."),
  mcq("bk2-pat-407", "Rising AFP with threshold growth on MRI in cirrhosis means HCC; surveillance that caught it was what?", ["No surveillance", "6 monthly ultrasound with AFP", "Yearly CT", "No imaging"], 1, "Scheduled screening catches curable lesions; threshold growth confirms radiologically while AFP alone never diagnoses. Adherence saves.", ["Incorrect. Screening caught it.", "Correct. Twice yearly US AFP.", "Incorrect. Radiation excess.", "Incorrect. Imaging is protocol."], "Cirrhosis watches twice yearly."),
  mcq("bk2-pat-408", "Painless progressive jaundice with CA19-9 rise and PSC history is cholangiocarcinoma; hilar staging uses what?", ["Milan", "Bismuth-Corlette extent guiding resection or transplant protocol", "Gleason", "No staging"], 1, "Hilar confluence extent decides Roux-en-Y resectability; stenting palliates while PSC surveillance misses early. CA19-9 supports, never proves.", ["Incorrect. HCC criteria differ.", "Correct. Bismuth hilar.", "Incorrect. Prostate differs.", "Incorrect. Staging guides knife."], "Hilar bile cancer: Bismuth maps."),
  mcq("bk2-pat-409", "Central stellate scar in a young woman with no OCP bleed is FNH; management is what?", ["Resect always", "Observe; adenoma with OCP bleed instead resects", "Transplant", "No imaging"], 1, "Fibrous scar with benign course contrasts adenoma haemorrhage risk on hormones; OCP stopped with resection debated. Haemangioma nodules enhance peripherally.", ["Incorrect. Benign observed.", "Correct. FNH watches.", "Incorrect. Organs spared.", "Incorrect. Imaging characterises."], "Central scar young liver: FNH observes."),
  mcq("bk2-pat-410", "Haemangioma with peripheral nodular discontinuous enhancement is managed how?", ["Resect always", "Observe; Kasabach-Merritt consumptive cases intervene", "Embolise always", "No imaging"], 1, "Benign vascular tufts fill centripetally safely; giant lesions with platelet trapping (Kasabach-Merritt) or rupture risk act. Biopsy bleeds avoided.", ["Incorrect. Benign observed.", "Correct. Haemangioma watches.", "Incorrect. Selected only.", "Incorrect. Imaging diagnoses."], "Nodular fill haemangioma: observe.")]);

add("pat-gallbladder-pancreas", "Gallbladder, biliary and pancreatic pathology", "gallbladder_biliary_pancreatitis_pancreatic_tumours", "Gallbladder, Biliary and Pancreatic Pathology",
 ["Gallstones and cholecystitis", "Gallbladder cancer and biliary emergencies", "Acute pancreatitis Atlanta", "Chronic pancreatitis and cystic tumours"],
 [step("**Gallstones** sort by chemistry: **cholesterol stones** (obesity, OCP, rapid weight loss, clofibrate; supersaturated bile) versus **black pigment** (haemolysis, cirrhosis, sterile) versus **brown pigment** (infected, stasis with E. coli and Ascaris, primary ductal). **Acute cholecystitis** (cystic duct stone, **Murphy sign** arresting inspiration, fever with leukocytosis, ultrasound wall thickening with pericholecystic fluid) gets early **laparoscopic cholecystectomy** with antibiotics; **Charcot triad** (pain, fever, jaundice) marks cholangitis while **Reynolds pentad** adds shock with confusion, and **Courvoisier law** (palpable gallbladder with jaundice is malignant, not stone) redirects.", "Fatty forty female OCP stones are cholesterol. Murphy arresting breath is cholecystitis: operate early."),
  step("**Gallbladder cancer** (elderly women, large stones, **porcelain gallbladder** calcification, anomalous pancreaticobiliary junction) presents late with jaundice and weight loss; cholecystectomy cures incidental T1 while advanced needs extended resection with palliation. **Biliary emergencies** sort by triads: cholangitis (Charcot, ERCP drainage with antibiotics), gallstone ileus (Rigler triad: obstruction with pneumobilia and ectopic stone, enterolithotomy), Mirizzi (impacted cystic stone compressing hepatic duct), emphysematous cholecystitis (diabetics, gas, urgent surgery). Porcelain prophylactically resects debated.", "Palpable gallbladder with jaundice is cancer until proven: Courvoisier. Porcelain calcified sac threatens malignancy."),
  step("**Acute pancreatitis** (gallstones, alcohol, hypertriglyceridaemia over 1000, hypercalcaemia, drugs like azathioprine, ERCP, mumps) autodigests with epigastric pain radiating to back relieved leaning forward; **lipase** (specific, longer than amylase) with contrast CT (**BISAP** severity, Atlanta classification) stages. Management is aggressive fluids, analgesia, antiemetics, early enteral feeding, ERCP only in cholangitis or persistent obstruction; **infected necrosis** (gas, procalcitonin, FNA) needs step up drainage with necrosectomy debated, sterile necrosis observes. Pseudocysts maturing over 4 weeks drain if symptomatic.", "Back boring pain with high lipase is pancreatitis: fluids, feed early, ERCP only if cholangitic. Gas in necrosis infects: drain up."),
  step("**Chronic pancreatitis** (alcohol, smoking, PRSS1 hereditary, autoimmune IgG4 sausage pancreas with steroids, pancreas divisum) calcifies with ductal stones, **steatorrhoea** (lipase lost first), diabetes and pseudocysts; **faecal elastase** diagnoses insufficiency treated with enzyme replacement. **Cystic tumours** sort malignant risk: **serous** (central scar, benign, observe), **mucinous MCN** (ovarian stroma, body tail women, resect), **IPMN** (main duct dilates, mural nodules, Whipple or surveillance by Sendai), **PDAC** (**double duct sign**, desmoplasia, CA19-9, painless jaundice with Courvoisier, Whipple if resectable, FOLFIRINOX palliates).", "Calcified pancreas with greasy stools is chronic: replace enzymes. Double duct elderly jaundice is PDAC: stage for Whipple.", tbl(["Biliary", "Sign", "Knife"], [["Cholecystitis", "Murphy", "Lap chole"], ["Cholangitis", "Charcot", "ERCP drain"], ["PDAC", "Double duct", "Whipple"], ["Serous cyst", "Central scar", "Observe"]]))],
 ["Murphy arresting breath: cholecystitis", "Palpable sac with jaundice: cancer", "Lipase back pain: fluids, feed early", "Double duct jaundice: PDAC Whipple"],
 "Cholesterol supersaturation nucleates stones that obstruct and infect; trypsinogen activates intrapancreatically autodigesting fat into saponification (Grey Turner and Cullen ecchymoses), and KRAS driven ductal clones desmoplase into double duct obstruction.",
 ["Cholecystitis versus cholangitis by Murphy and Charcot", "Pseudocyst versus walled off necrosis by timing and debris", "Serous versus mucinous cysts by scar and stroma"],
 ["Ultrasound Murphy with HIDA in biliary pain", "Lipase with BISAP and contrast CT in back pain", "Triple phase pancreas with CA19-9 in double duct jaundice"],
 [mcq("bk2-pat-411", "Obesity with OCP use and rapid weight loss forms which stones and prevented how?", ["Pigment; no prevention", "Cholesterol stones with weight control and ursodiol debated", "No stones", "Surgery always"], 1, "Supersaturated bile nucleates cholesterol; gradual loss with activity prevents while crash diets precipitate. Pigment stones follow haemolysis or infection instead.", ["Incorrect. Chemistry differs.", "Correct. Cholesterol, gradual loss.", "Incorrect. Stones form.", "Incorrect. Prevention first."], "Fat forty OCP: cholesterol stones."),
  mcq("bk2-pat-412", "Black pigment stones in haemolysis differ from brown by which features?", ["Same", "Black sterile in gallbladder versus brown infected primary ductal", "Both infected", "No difference"], 1, "Unconjugated bilirubin precipitates sterilely in haemolytics while stasis with bacteria browns ducts (Ascaris, strictures). Management follows location.", ["Incorrect. Sterility differs.", "Correct. Black sterile, brown infected.", "Incorrect. Black is sterile.", "Incorrect. Sites differ."], "Black sterile gallbladder; brown infected ducts."),
  mcq("bk2-pat-413", "Charcot triad with shock and confusion (Reynolds) in choledocholithiasis needs what?", ["Cholecystectomy alone", "Urgent ERCP drainage with antibiotics", "No treatment", "Laxatives"], 1, "Ascending cholangitis septicaemias rapidly; biliary decompression with broad cover saves while cholecystectomy follows electively. Delays kill.", ["Incorrect. Ducts need draining.", "Correct. ERCP septic cholangitis.", "Incorrect. Sepsis kills.", "Incorrect. Obstruction persists."], "Charcot plus shock: ERCP now."),
  mcq("bk2-pat-414", "Palpable gallbladder with painless jaundice (Courvoisier) suggests malignancy; next step is what?", ["Reassure stones", " stage pancreaticobiliary malignancy with triple phase imaging", "Discharge", "Antacids"], 1, "Chronic stone fibrosis prevents distension while malignant obstruction balloons the sac; PDAC or cholangiocarcinoma hunt follows. Stones rarely palpate.", ["Incorrect. Law inverts.", "Correct. Courvoisier malignant.", "Incorrect. Cancer looms.", "Incorrect. Obstruction persists."], "Palpable sac jaundice: cancer hunt."),
  mcq("bk2-pat-415", "Rigler triad (obstruction, pneumobilia, ectopic stone) is gallstone ileus; management is what?", ["Cholecystectomy always", "Enterolithotomy relieving obstruction, biliary surgery later", "No surgery", "Laxatives"], 1, "Fistulising stones impact ileum in elderly women; milk or open removal with fistula addressed electively. One stage risks frail patients.", ["Incorrect. Bowel first.", "Correct. Open bowel, stage biliary.", "Incorrect. Obstruction strangulates.", "Incorrect. Stones never dissolve."], "Rigler elderly obstruction: enterolithotomy."),
  mcq("bk2-pat-416", "Epigastric pain boring to back with lipase 5x normal after gallstones is pancreatitis; fluids and feeding are how?", ["Restrict fluids, starve", "Aggressive crystalloids with early enteral feeding", "No fluids", "TPN always"], 1, "Third spacing demands volume while gut rest harms (translocation); nasojejunal feeding preserves barrier. ERCP only with cholangitis.", ["Incorrect. Volume saves.", "Correct. Fill and feed early.", "Incorrect. Kidneys fail dry.", "Incorrect. Enteral beats TPN."], "Pancreatitis: fill vessels, feed gut."),
  mcq("bk2-pat-417", "Gas in pancreatic necrosis with procalcitonin rise means infection; management steps how?", ["Immediate open necrosectomy", "Step up percutaneous drainage with minimally invasive necrosectomy as needed", "No action", "Steroids"], 1, "Infected necrosis kills without source control; drains with FNA proof escalate while sterile necrosis observes. Antibiotics penetrate poorly alone.", ["Incorrect. Step up first.", "Correct. Drain up infected.", "Incorrect. Sepsis kills.", "Incorrect. Steroids worsen."], "Gassy necrosis: drain stepwise."),
  mcq("bk2-pat-418", "Calcified pancreas with steatorrhoea and diabetes is chronic pancreatitis; insufficiency testing uses what?", ["Lipase alone", "Faecal elastase with enzyme replacement", "No test", "Amylase"], 1, "Elastase survives transit marking lipase loss earliest; enzymes with meals plus diabetes care follow. Alcohol cessation slows.", ["Incorrect. Elastase survives.", "Correct. Elastase, replace enzymes.", "Incorrect. Tests exist.", "Incorrect. Amylase fluctuates."], "Greasy calcified pancreas: elastase."),
  mcq("bk2-pat-419", "Main duct IPMN with mural nodules is managed how versus serous cystadenoma?", ["Same observe", "IPMN resects (malignant potential) while serous central scar observes", "No difference", "Aspirate always"], 1, "Sendai size and nodules gate Whipple or surveillance; serous microcysts with scar stay benign. Mucinous MCN similarly resects.", ["Incorrect. Risk differs.", "Correct. IPMN resects, serous watches.", "Incorrect. Malignancy splits.", "Incorrect. Surgery decides."], "Mural nodule duct: resect IPMN."),
  mcq("bk2-pat-420", "Double duct sign with painless jaundice and weight loss in elderly is PDAC; resectability needs what?", ["No staging", "Triple phase CT with vascular involvement mapping for Whipple candidacy", "Biopsy always", "No surgery"], 1, "SMA and celiac encasement vetoes curative Whipple; borderline neoadjuvant debates follow while FOLFIRINOX palliates. CA19-9 supports.", ["Incorrect. Vessels decide.", "Correct. Map vessels for Whipple.", "Incorrect. Resectable skips biopsy.", "Incorrect. Selected cure."], "Double duct elderly: map vessels.")]);

add("pat-tubulointerstitial-cystic", "Tubulointerstitial disease and renal cysts", "tubulointerstitial_nephritis_pyelonephritis_cystic", "Tubulointerstitial Disease, Pyelonephritis and Renal Cysts",
 ["ATN ischaemic and toxic", "AIN drugs and eosinophils", "Pyelonephritis and reflux", "Cystic diseases ADPKD to medullary"],
 [step("**Acute tubular necrosis** (ischaemia from shock or sepsis, nephrotoxins like aminoglycosides, cisplatin, amphotericin and contrast) sheds epithelium into **muddy brown granular casts** with **FENa over 2 percent** (versus under 1 percent in prerenal) and oliguria; phases run initiation, maintenance and diuretic recovery with polyuria. Management is fluids with pressors, stop toxins, dialyse complications; most recover if the insult lifts. Contrast gets hydration with bicarbonate or NAC debates; rhabdomyolysis (myoglobin, CK, tea coloured urine) alkalinises with fluids.", "Muddy brown casts with high FENa after shock are ATN: perfuse, dialyse complications. Contrast kidneys hydrate first."),
  step("**Acute interstitial nephritis** (beta lactams, NSAIDs with minimal change overlap, PPIs, allopurinol, infections) presents with fever, rash and arthralgia weeks after drugs, **eosinophils** in blood and urine (Hansel stain), **WBC casts** and rising creatinine; biopsy shows interstitial infiltrates sparing glomeruli. Treatment is **stop the drug with steroids** debated for severe or prolonged cases; PPIs hide ubiquitously so medication review matters. Chronic analgesic abuse papillary necroses separately.", "Fever rash eosinophils weeks after penicillin with WBC casts is AIN: stop drug, steroids debated. Review PPIs."),
  step("**Acute pyelonephritis** (ascending E. coli with P fimbriae, **WBC casts** proving tubular origin, fever with loin pain and dysuria) is treated by culture guided fluoroquinolones or ceftriaxone (men, pregnancy, obstruction admitted); **vesicoureteric reflux** (childhood recurrent UTI, MCU grading, prophylaxis debated, reimplantation high grades) scars into reflux nephropathy with hypertension. **Chronic pyelonephritis** (coarse asymmetric scars with blunted calyces) differs from analgesic nephropathy (papillary necrosis with calcifications). Emphysematous pyelonephritis (diabetics, gas) nephrectomises emergently.", "WBC casts with loin pain are pyelonephritis: culture then cover. Childhood recurrent UTI refluxes: MCU grades."),
  step("**Cystic diseases** sort by gene and age: **ADPKD** (**PKD1** severe, PKD2 milder, bilateral enlarged kidneys, **berry aneurysms** with subarachnoid risk, liver cysts, mitral prolapse, tolvaptan slowing), **ARPKD** (PKHD1, infants with oligohydramnios and Potter sequence, congenital hepatic fibrosis), medullary sponge (tubular ectasia with stones and haematuria, benign), medullary cystic (tubulointerstitial fibrosis with hyperuricaemia), acquired cystic (dialysis, RCC risk). Simple cysts (Bosniak I) observe; complex (Bosniak III-IV) resects.", "Enlarged cystic kidneys with berry aneurysms are ADPKD: screen brain vessels. Dialysis cysts watch for RCC.", tbl(["Kidney", "Cast", "Fix"], [["ATN", "Muddy brown", "Perfuse"], ["AIN", "WBC, eosinophils", "Stop drug"], ["Pyelo", "WBC casts", "Culture cover"], ["ADPKD", "No casts", "Tolvaptan"]]))],
 ["Muddy brown high FENa: ATN", "Drug fever eosinophils WBC casts: AIN", "WBC casts loin pain: pyelonephritis", "Big cystic kidneys aneurysms: ADPKD"],
 "Ischaemic ATP loss detaches tubular cells plugging lumens while drug haptens inflame interstitium sparing glomeruli; ascending fimbriated bacilli scar refluxing kidneys asymmetrically, and polycystin failure cystifies tubules systemically.",
 ["ATN versus prerenal by FENa and casts", "AIN versus ATN by eosinophils and timing", "Reflux versus analgesic scars by symmetry and papillae"],
 ["Urine microscopy with FENa in oliguria", "Hansel eosinophils with drug review in rising creatinine", "MCU with DMSA scarring in childhood UTI"],
 [mcq("bk2-pat-421", "Muddy brown granular casts with FENa 3 percent after prolonged hypotension indicate what?", ["Prerenal azotaemia", "ATN needing perfusion with dialysis for complications", "Glomerulonephritis", "Obstruction"], 1, "Tubular necrosis leaks sodium (FENa high) shedding epithelium; prerenal concentrates with FENa under 1 percent. Fluids with pressors recover most.", ["Incorrect. FENa is high.", "Correct. ATN muddy brown.", "Incorrect. RBC casts differ.", "Incorrect. No hydronephrosis."], "Muddy casts high FENa: ATN."),
  mcq("bk2-pat-422", "Rhabdomyolysis with tea coloured urine and CK 20000 threatens kidneys; prevention is what?", ["No fluids", "Aggressive saline with urinary alkalinisation debated", "Dialysis always", "No action"], 1, "Myoglobin precipitates acidically obstructing; volume with bicarbonate flushes while compartment pressures watched. Crush injuries warn.", ["Incorrect. Volume saves.", "Correct. Flood alkalinised.", "Incorrect. Prevention first.", "Incorrect. Kidneys fail fast."], "Crush tea urine: flood it."),
  mcq("bk2-pat-423", "Fever with rash and eosinophilia 3 weeks after amoxicillin plus WBC casts is AIN; therapy is what?", ["Continue drug", "Stop amoxicillin with steroids debated in severe cases", "Dialysis always", "No action"], 1, "Hypersensitivity interstitium recovers once trigger leaves; steroids hasten prolonged injury while PPIs reviewed ubiquitously. Biopsy proves when doubted.", ["Incorrect. Trigger persists.", "Correct. Stop, steroids debated.", "Incorrect. Recovery rules.", "Incorrect. Creatinine climbs."], "Drug fever eosinophil casts: stop it."),
  mcq("bk2-pat-424", "NSAID induced AIN with nephrotic range proteinuria suggests which overlap and managed how?", ["Pure AIN", "Minimal change overlap needing steroids", "No disease", "FSGS always"], 1, "NSAIDs fuse interstitial nephritis with podocyte fusion; steroids remit while drug stops. Biopsy shows dual lesions.", ["Incorrect. Proteinuria is glomerular.", "Correct. Overlap, steroids.", "Incorrect. Protein is real.", "Incorrect. Lesions differ."], "NSAID nephrotic AIN: steroids."),
  mcq("bk2-pat-425", "Fever with loin pain, dysuria and WBC casts in a pregnant woman is pyelonephritis; admission and drug are what?", ["Outpatient nitrofurantoin", "Admit with ceftriaxone (nitrofurantoin avoids tissue)", "No treatment", "Ciprofloxacin"], 1, "Bacteraemia threatens preterm labour; beta lactams penetrate kidney while nitrofurantoin stays luminal. Cultures tailor.", ["Incorrect. Tissue needs cover.", "Correct. Admit, ceftriaxone.", "Incorrect. Sepsis threatens.", "Incorrect. Quinolones avoid pregnancy."], "Pregnant loin pain casts: admit ceftriaxone."),
  mcq("bk2-pat-426", "Recurrent febrile UTI in a 4 year old with scarring suggests VUR; workup is what?", ["No imaging", "MCU grading with DMSA scarring and prophylaxis debated", "CT always", "No follow up"], 1, "Reflux grades gate prophylaxis versus reimplantation; DMSA maps scars with blood pressure followed lifelong. Sibling screening debates.", ["Incorrect. Kidneys scar.", "Correct. MCU DMSA reflux.", "Incorrect. Radiation sparing.", "Incorrect. Hypertension follows."], "Child febrile UTI scars: MCU."),
  mcq("bk2-pat-427", "Emphysematous pyelonephritis with gas in a diabetic is managed how?", ["Antibiotics alone", "Urgent nephrectomy with broad cover and sugar control", "Observe", "Stents only"], 1, "Gas forming organisms necrotise rapidly fatal medically; surgery with resuscitation saves while percutaneous drains selected stable. Glycaemia corrected.", ["Incorrect. Gas kills.", "Correct. Nephrectomy gas.", "Incorrect. Necrosis spreads.", "Incorrect. Drains select."], "Diabetic renal gas: remove kidney."),
  mcq("bk2-pat-428", "Bilateral enlarged cystic kidneys with berry aneurysm and liver cysts is ADPKD; the gene and brain step are what?", ["PKHD1; no screen", "PKD1 usually with MRA screening for aneurysms", "No gene", "Dialysis only"], 1, "Polycystin failure cystifies systemically; family MRA with blood pressure control prevents subarachnoid bleed. Tolvaptan slows growth.", ["Incorrect. Recessive is infantile.", "Correct. PKD1, MRA brain.", "Incorrect. Dominant families.", "Incorrect. Decades precede dialysis."], "Big cystic kidneys aneurysms: PKD1, MRA."),
  mcq("bk2-pat-429", "Infant with oligohydramnios, Potter facies and palpable kidneys suggests ARPKD; counselling is what?", ["Dominant", "Recessive PKHD1 with hepatic fibrosis watched and recurrence quoted", "No risk", "Acquired"], 1, "Collecting duct ectasia with congenital hepatic fibrosis recurs 25 percent; pulmonary hypoplasia kills neonatally while survivors transplant. Siblings screen.", ["Incorrect. Recessive infantile.", "Correct. ARPKD counsel.", "Incorrect. Risk is quarter.", "Incorrect. Congenital."], "Potter cystic infant: recessive counsel."),
  mcq("bk2-pat-430", "Dialysis acquired cystic kidneys with enhancing nodule raise which fear and managed how?", ["No fear", "RCC with Bosniak guided resection and transplant workup paused", "Infection only", "No imaging"], 1, "Acquired cysts dysplasias into tumours; complex enhancement resects while screening intensifies. Transplant waits cancer free intervals.", ["Incorrect. Tumours brew.", "Correct. Acquired cyst RCC.", "Incorrect. Enhancement proves.", "Incorrect. Imaging stages."], "Dialysis cyst nodule: resect.")]);

add("pat-renal-urinary-tumours", "Renal cell carcinoma, Wilms and urothelial cancer", "rcc_wilms_urothelial_paraneoplastic", "RCC, Wilms Tumour and Urothelial Cancer",
 ["RCC subtypes and VHL", "Paraneoplastic syndromes", "Wilms triphasic childhood tumour", "Urothelial bladder cancer and BCG"],
 [step("**Renal cell carcinoma** (smoking, obesity, hypertension, dialysis acquired cysts) subtypes sort genetics: **clear cell** (**VHL** loss, hypervascular, commonest), papillary (MET, multifocal), **chromophobe** (Birt-Hogg-Dube, pale, best prognosis), collecting duct (aggressive). Classic triad (haematuria, flank pain, palpable mass) now rare; incidental imaging finds most. Treatment is **partial or radical nephrectomy** (cytoreductive debated) with **TKI and checkpoint inhibitors** (sunitinib, nivolumab) for metastatic; active surveillance suits small elderly masses.", "Hypervascular clear kidney mass is RCC: VHL lost. Small elderly masses watch; spread gets TKI plus immunotherapy."),
  step("**Paraneoplastic syndromes** flag RCC: **polycythaemia** (ectopic EPO), **hypercalcaemia** (PTHrP), hypertension (renin), **Stauffer syndrome** (nonmetastatic hepatic dysfunction with raised ALP), Cushing (ACTH), amyloid. New varicocele (left gonadal vein obstruction) or IVC thrombus warns locally advanced disease; lung cannonballs seed commonly. Paraneoplasia resolves with nephrectomy and recurs with relapse, serving as markers.", "New polycythaemia with kidney mass is EPO paraneoplasia. Left varicocele with haematuria is renal vein thrombus."),
  step("**Wilms tumour** (nephroblastoma, WT1 and WT2, triphasic blastemal with epithelial and stromal elements) presents as **painless abdominal mass** in toddlers that **crosses midline** (versus neuroblastoma which does not cross and calcifies with raised catecholamines); associations include **WAGR** (aniridia, genitourinary anomalies, retardation), Denys-Drash and **Beckwith-Wiedemann**. Treatment (vincristine with actinomycin and doxorubicin, nephrectomy timing by protocol) cures over 90 percent; **anaplasia** (p53) worsens needing intensification. Lung metastases resect.", "Painless midline crossing toddler mass is Wilms: chemo cures mostly. Aniridia plus mass is WAGR: delete WT1."),
  step("**Urothelial carcinoma** (smoking, **aniline dyes** and aromatic amines, cyclophosphamide, aristolochic acid, chronic schistosoma haematobium squamous) presents with **painless haematuria**; **carcinoma in situ** (flat high grade, BCG responsive) with papillary Ta/T1 graded low versus high. Non muscle invasive gets **TURBT with intravesical BCG** (live attenuated, cystitis with BCG sepsis caution); muscle invasive needs **neoadjuvant cisplatin with radical cystectomy** and diversion. Upper tract (renal pelvis, ureter) mirrors bladder with nephroureterectomy.", "Painless haematuria in a smoker is urothelial until scoped: TURBT stages. Flat red high grade is CIS: BCG.", tbl(["Urinary tumour", "Gene", "Fix"], [["Clear RCC", "VHL", "Nephrectomy"], ["Wilms", "WT1/WT2", "Chemo cures"], ["Bladder", "Smoking/dyes", "TURBT plus BCG"], ["Chromophobe", "BHD", "Best outlook"]]))],
 ["Clear hypervascular mass: VHL RCC", "Polycythaemia kidney mass: EPO", "Crossing midline toddler mass: Wilms", "Painless smoker haematuria: urothelial"],
 "VHL loss stabilises HIF driving VEGF hypervascularity while WT1 loss freezes metanephric blastema into triphasic tumours; aromatic amines adduct urothelial DNA field cancerising the tract, and anaplastic p53 clones resist therapy.",
 ["Clear cell versus chromophobe by vessels and prognosis", "Wilms versus neuroblastoma by midline and catecholamines", "CIS versus papillary by flatness and BCG response"],
 ["Triple phase kidney with chest staging in haematuria", "Abdominal mass with WT workup and chest CT in toddlers", "Cystoscopy with cytology in painless haematuria"],
 [mcq("bk2-pat-431", "Hypervascular clear cell kidney mass with polycythaemia suggests RCC with which mechanism and gene?", ["EPO deletion", "VHL loss with ectopic EPO paraneoplasia", "No gene", "BCR-ABL"], 1, "HIF driven EPO escapes renal regulation; nephrectomy normalises counts while TKI with immunotherapy treats spread. Varicocele warns venous thrombus.", ["Incorrect. EPO is excess.", "Correct. VHL EPO mass.", "Incorrect. Genetics define.", "Incorrect. Leukaemia differs."], "Clear mass plus red cells: VHL EPO."),
  mcq("bk2-pat-432", "Stauffer syndrome in RCC is what and managed how?", ["Liver metastases always", "Nonmetastatic hepatic dysfunction resolving with nephrectomy", "Hepatitis", "No action"], 1, "Cytokine cholestasis without tumour (raised ALP, prolonged PT) reverses on resection; metastases instead persist radiologically. Recurrence re-raises enzymes.", ["Incorrect. No tumour in liver.", "Correct. Stauffer reverses.", "Incorrect. Serology negative.", "Incorrect. Marker watched."], "RCC raised ALP clean liver: Stauffer."),
  mcq("bk2-pat-433", "Left new varicocele with haematuria suggests renal vein thrombus from RCC because of which anatomy?", ["Right drains IVC", "Left gonadal vein drains renal vein obstructed by tumour", "No anatomy", "Varicocele always benign"], 1, "Tumour thrombus climbs cava (level staging) blocking gonadal return; Doppler with IVC imaging stages while nephrectomy with thrombectomy treats. Idiopathic teenage varicoceles differ.", ["Incorrect. Left is renal.", "Correct. Renal vein blocked.", "Incorrect. Anatomy explains.", "Incorrect. New adult alarms."], "Adult new left varicocele: renal mass."),
  mcq("bk2-pat-434", "Metastatic clear cell RCC with good performance is systemically treated how?", ["Chemotherapy", "TKI with checkpoint inhibitors (sunitinib, nivolumab combinations)", "Hormones", "No therapy"], 1, "Angiogenic plus immune blockade extends survival; cytoreductive nephrectomy debates select while active surveillance suits indolent. Chemo resists RCC.", ["Incorrect. RCC chemoresists.", "Correct. TKI plus IO.", "Incorrect. Hormones fail.", "Incorrect. Therapy extends."], "Spread clear cell: TKI plus checkpoint."),
  mcq("bk2-pat-435", "Painless toddler abdominal mass crossing midline without calcifications is Wilms; associations include what?", ["No associations", "WAGR, Denys-Drash and Beckwith-Wiedemann", "Down only", "NF1 only"], 1, "WT locus neighbours aniridia and growth genes; screening (abdominal US) runs in syndromes while chemo cures mostly. Neuroblastoma calcifies with catecholamines.", ["Incorrect. Syndromes cluster.", "Correct. WAGR and overgrowth.", "Incorrect. Specific loci.", "Incorrect. Different genes."], "Crossing painless mass: Wilms syndromes."),
  mcq("bk2-pat-436", "Wilms with diffuse anaplasia (p53) changes therapy how?", ["Same low risk", "Intensification with doxorubicin and radiotherapy as outlook worsens", "No treatment", "Surgery only"], 1, "Anaplastic histology resists standard two drug cure; staging with lung status intensifies while favourable histology de-escalates. Biology beats size.", ["Incorrect. Anaplasia worsens.", "Correct. Intensify anaplastic.", "Incorrect. Treatment escalates.", "Incorrect. Multimodal needed."], "Anaplastic Wilms intensifies."),
  mcq("bk2-pat-437", "Painless haematuria in a dye worker is urothelial until proven; first investigation is what?", ["Ultrasound only", "Cystoscopy with cytology and upper tract imaging", "No scope", "Urine culture"], 1, "Direct visualisation biopsies flat CIS invisible on scans; aromatic amine field change watches whole tract. Culture excludes infection first.", ["Incorrect. Flat lesions hide.", "Correct. Scope smoker haematuria.", "Incorrect. Scoping stages.", "Incorrect. Sterile usually."], "Dye haematuria: scope first."),
  mcq("bk2-pat-438", "Flat erythematous high grade bladder lesion (CIS) is treated how?", ["Cystectomy always", "TURBT with intravesical BCG and surveillance", "No treatment", "Systemic chemo"], 1, "Live mycobacterial immunotherapy eradicates flat high grade disease; BCG sepsis with irritative symptoms watched while refractory cases cystectomise. Papillary low grade fulgurates.", ["Incorrect. Bladder spared often.", "Correct. BCG flat CIS.", "Incorrect. CIS threatens.", "Incorrect. Local suffices."], "Flat red high grade: BCG."),
  mcq("bk2-pat-439", "Muscle invasive bladder cancer with fit kidneys is treated curatively how?", ["BCG alone", "Neoadjuvant cisplatin with radical cystectomy and diversion", "Radiation only", "No cure"], 1, "Systemic downstaging plus extirpation cures while diversion (ileal conduit, neobladder) restores flow. Bladder preservation trimodality suits selected.", ["Incorrect. Muscle needs removal.", "Correct. Chemo plus cystectomy.", "Incorrect. Trimodality selected.", "Incorrect. Cure is real."], "Muscle invasive: chemo then cystectomy."),
  mcq("bk2-pat-440", "Cyclophosphamide haemorrhagic cystitis with later bladder cancer links by which metabolite and prevented how?", ["No link", "Acrolein with mesna protection and hydration", "Parent drug", "No prevention"], 1, "Acrolein injures urothelium into fibrosis then field cancer; mesna binds with fluids flushing while ifosfamide shares risk. Surveillance follows.", ["Incorrect. Metabolite injures.", "Correct. Acrolein, mesna.", "Incorrect. Metabolite, not parent.", "Incorrect. Mesna protects."], "Cyclo bladder: acrolein, mesna.")]);

add("pat-male-genital", "Male genital pathology: prostate, testis, penis and scrotum", "male_genital_prostate_testis_torsion", "Male Genital Pathology: Prostate, Testis, Penis and Scrotum",
 ["BPH zones and therapy", "Prostate cancer Gleason and bone", "Testicular tumours and markers", "Torsion, varicocele and infections"],
 [step("**Benign prostatic hyperplasia** (dihydrotestosterone driven **transitional zone** nodules with bladder outlet obstruction, hesitancy with nocturia and retention) is treated by **alpha blockers** (tamsulosin relaxing smooth muscle) then **5 alpha reductase inhibitors** (finasteride shrinking), with **TURP** for refractory or complicated disease (retention, stones, renal injury). PSA rises modestly with volume; biopsy only when cancer suspected. Chronic prostatitis (pelvic pain with cultures often negative) differs by tenderness with antibiotics debated.", "Transitional zone nodules blocking old men are BPH: block alpha, shrink with finasteride, resect when complicated."),
  step("**Prostate adenocarcinoma** (peripheral zone, **Gleason score** grading glands, PSA screening debates, **osteoblastic bone metastases** with high alkaline phosphatase) is managed by risk: active surveillance (low risk), prostatectomy or radiotherapy (localised), **androgen deprivation** (leuprolide, bicalutamide, orchidectomy) for advanced with docetaxel or abiraterone added. Back pain with high PSA in elders seeds spine; cord compression (steroids with urgent decompression) threatens. Prostatitis and BPH raise PSA benignly; density and velocity refine.", "Peripheral zone hard nodule with high PSA is cancer: Gleason grades. Osteoblastic spine mets mark prostate: deprive androgens."),
  step("**Testicular germ cell tumours** (young men, **cryptorchidism** risk, painless mass that does not transilluminate) split into **seminoma** (radiosensitive, sheets with lymphocytes, **PLAP** positive, orchidectomy with surveillance or radiotherapy) and **nonseminoma** (**yolk sac AFP** raised, **choriocarcinoma hCG** with haemorrhage, embryonal aggressive, teratoma mixed). Staging (retroperitoneal nodes, lung) gates **RPLND** versus BEP chemotherapy (bleomycin lungs, cisplatin kidneys); tumour markers (AFP, hCG, LDH) stage and follow. Sex cord tumours (Leydig with precocity, Sertoli) are rarer.", "Painless solid young testis is germ cell until orchidectomy proves: AFP yolk sac, hCG choriocarcinoma. Seminoma radiosensitively surveils."),
  step("**Emergencies and benign scrotals** sort fast: **testicular torsion** (adolescent sudden pain with vomiting, **bell clapper** deformity, absent cremasteric, Doppler flow lost) needs **detorsion within 6 hours with bilateral orchiopexy**; epididymo-orchitis (chlamydia under 35, E. coli over 35, Prehn relief, antibiotics by age) mimics. **Left varicocele** (bag of worms, infertility, renal mass in new adult onset), hydrocele (transilluminates), spermatocele, and **penile SCC** (HPV, phimosis, lichen sclerosus, partial penectomy with node dissection) complete patterns.", "Sudden twisted teen testis with lost Doppler is torsion: untwist in 6 hours, fix both. Left bag of worms infertile is varicocele.", tbl(["Scrotum", "Pain", "Knife"], [["Torsion", "Sudden vomit", "Orchiopexy 6h"], ["Epididymitis", "Gradual relief lift", "Antibiotics"], ["Tumour", "Painless solid", "Orchidectomy"], ["Varicocele", "Dull left", "Ligate infertile"]]))],
 ["Transitional nodules old obstruction: BPH", "Peripheral hard PSA bone: prostate cancer", "Painless young solid: germ cell", "Sudden twisted teen: torsion 6 hours"],
 "DHT hyperplasias transition while peripheral clones dedifferentiate into Gleason patterns metastasising osteoblastically; isochromosome 12p drives germ cells that AFP or hCG betray, and bell clapper mobility twists spermatic cords ischaemically.",
 ["BPH versus cancer by zone and Gleason", "Seminoma versus nonseminoma by markers and radio response", "Torsion versus epididymitis by onset and Prehn"],
 ["PSA with rectal exam and MRI fusion biopsy in nodules", "Testicular ultrasound with AFP, hCG and LDH in masses", "Doppler in sudden scrotal pain within hours"],
 [mcq("bk2-pat-441", "Transitional zone nodules with nocturia and retention in a 70 year old are BPH; first therapy is what?", ["Finasteride first", "Alpha blockers relaxing outlet with finasteride added", "Prostatectomy always", "No treatment"], 1, "Tamsulosin eases dynamic obstruction quickly while 5ARI shrinks slowly; TURP waits retention, stones or renal injury. PSA density watches cancer.", ["Incorrect. Slow shrink second.", "Correct. Alpha first, add finasteride.", "Incorrect. Surgery is complicated.", "Incorrect. Retention threatens."], "Old outlet blocked: alpha first."),
  mcq("bk2-pat-442", "Peripheral zone hard nodule with PSA 25 and osteoblastic spine lesions is prostate cancer; systemic therapy is what?", ["Antibiotics", "Androgen deprivation with docetaxel or abiraterone in advanced", "TURP cures", "No therapy"], 1, "Hormone sensitivity palliates years; castration resistance adds chemo or androgen synthesis blockade while cord compression decompresses urgently. TURP relieves outlet only.", ["Incorrect. Bacteria absent.", "Correct. Deprive androgens.", "Incorrect. Palliation, not cure.", "Incorrect. Bones need therapy."], "Hard peripheral PSA spine: deprive."),
  mcq("bk2-pat-443", "Gleason 3+4 versus 4+3 prostate cancer differ prognostically how?", ["Same", "4+3 (pattern 4 dominant) behaves worse needing treatment escalation", "No grading", "PSA decides"], 1, "Primary pattern dominance drives risk; 4+3 upgrades intermediate unfavourably while 3+3 surveils. Grade groups modernise sums.", ["Incorrect. Dominance matters.", "Correct. Four dominant worse.", "Incorrect. Grading guides.", "Incorrect. Histology leads."], "Four leading is worse prostate."),
  mcq("bk2-pat-444", "Painless non transilluminating young testicular mass is germ cell; markers sorting seminoma from nonseminoma are what?", ["No markers", "AFP (yolk sac) with hCG (choriocarcinoma) marking nonseminoma; seminoma PLAP", "PSA", "CEA"], 1, "Elevated AFP never occurs in pure seminoma; hCG with haemorrhage marks choriocarcinoma while LDH burdens. Orchidectomy stages all.", ["Incorrect. Markers stage.", "Correct. AFP hCG nonseminoma.", "Incorrect. Prostate differs.", "Incorrect. Colon differs."], "AFP or hCG raised: nonseminoma."),
  mcq("bk2-pat-445", "Cryptorchidism raises testicular cancer risk even after orchiopexy; the counsel is what?", ["No risk", "Early orchiopexy with lifelong self exam as risk persists", "Orchiopexy removes risk", "No follow up"], 1, "Undescended gonads malignify (seminoma commonest) despite repositioning; self exam with prompt ultrasound catches. Bilateral watches fertility.", ["Incorrect. Risk persists.", "Correct. Fix early, watch life.", "Incorrect. Risk remains.", "Incorrect. Exams save."], "Undescended fixed still watched."),
  mcq("bk2-pat-446", "BEP chemotherapy for nonseminoma threatens lungs and kidneys by which agents and guarded how?", ["No toxicity", "Bleomycin lungs with PFTs, cisplatin kidneys with hydration", "All safe", "No monitoring"], 1, "Bleomycin fibroses (smoking and oxygen worsen) while cisplatin tubules waste magnesium; dose caps with fluids protect. Etoposide leukaemias rarely.", ["Incorrect. Organs at stake.", "Correct. Lungs kidneys watched.", "Incorrect. Toxicities real.", "Incorrect. Monitoring saves."], "BEP: lungs bleo, kidneys cisplatin."),
  mcq("bk2-pat-447", "Sudden teen testicular pain with vomiting and absent cremasteric needs what within hours?", ["Antibiotics", "Surgical detorsion with bilateral orchiopexy inside 6 hours", "Observation", "Cold pack"], 1, "Bell clapper twists ischaemically necrosing; Doppler confirms while manual detorsion bridges to theatre. Epididymitis instead relieves lifting.", ["Incorrect. Ischaemia, not infection.", "Correct. Untwist 6 hours.", "Incorrect. Testis dies.", "Incorrect. Cold worsens."], "Twisted teen vomit: 6 hour untwist."),
  mcq("bk2-pat-448", "Gradual testicular pain relieved by lifting (Prehn) with dysuria in a 25 year old is epididymitis; organism and drug are what?", ["E. coli; cipro", "Chlamydia with ceftriaxone plus doxycycline", "Mumps always", "No treatment"], 1, "Sexually transmitted ascent inflames epididymis sparing flow on Doppler; partner therapy completes while older men grow coliforms. Torsion instead worsens lifting.", ["Incorrect. Older pattern.", "Correct. Chlamydia young, dual cover.", "Incorrect. Mumps is bilateral.", "Incorrect. Infection needs drugs."], "Young lifted relief: chlamydia cover."),
  mcq("bk2-pat-449", "New left varicocele with infertility in a 30 year old is ligated; new onset at 60 instead hunts what?", ["Nothing", "Renal mass obstructing gonadal vein", "Hernia", "Hydrocele"], 1, "Adult varix reflects venous block (RCC thrombus) not valves; imaging stages while youthful idiopathic ligates for fertility. Transillumination separates hydrocele.", ["Incorrect. Age alarms.", "Correct. Renal hunt at 60.", "Incorrect. Cough impulse differs.", "Incorrect. Light passes hydrocele."], "Old new varicocele: kidney hunt."),
  mcq("bk2-pat-450", "Non healing ulcer with phimosis and HPV positivity on glans is penile SCC; management is what?", ["Topical only", "Partial penectomy with node dissection by stage", "No treatment", "Antibiotics"], 1, "Chronic inflammation malignifies foreskin; conservative glansectomy suits low stage while groin dissection stages. Circumcision prevents.", ["Incorrect. Invasion needs knife.", "Correct. Resect with nodes.", "Incorrect. Cancer grows.", "Incorrect. Bacteria absent."], "Phimotic glans ulcer: resect with nodes.")]);

let fail = 0;
for (const m of M) {
  for (const s of m.steps) if (!s.tx.includes("**")) s.tx = "**Key point.** " + s.tx;
  const lesson = { v: 1, module: m.id, subject: "pathology", title: m.title, minutes: 6, steps: m.steps, quiz: m.mcqs.map((x) => x.id), src: [], refs: [REF], gen: "AI", run: "books2-path4", model: "muse-wonder (local authoring, no external API)", checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: 10 } };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.log("LESSON FAIL", m.id, probs); fail++; }
  fs.writeFileSync(path.join(ROOT, "prep/lessons/v1", m.id + ".json"), JSON.stringify(lesson, null, 1));
  if (m.kb) {
    const kb = { id: m.kb, name: m.kbName, aliases: m.aliases, class: "neoplastic", system: "Pathology", specialty: "Pathology", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "Robbins 9th (topic map, 2026-10-13)", pages: null, clinicalPearls: m.pearls, pathophysiology: m.patho, additionalDifferentials: m.diffs, additionalInvestigations: m.invs } };
    fs.writeFileSync(path.join(ROOT, "kb/reference", m.kb + ".json"), JSON.stringify(kb, null, 1));
  }
  const overlay = { topic: m.id, set: "maikbook2", v: 1, items: m.mcqs.map((x) => ({ prov: "SMD", gen: "hand", set: "maikbook2", d: 2, cog: "application", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } }, id: x.id, q: x.q, o: x.o, a: x.a, exp: x.exp, r: x.r, kp: x.kp })) };
  const dir = path.join(ROOT, "prep/overlays/maikbook2/pathology");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, m.id + ".json"), JSON.stringify(overlay, null, 1));
}
const ixPath = path.join(ROOT, "prep/lessons/v1/index.json");
const ix = JSON.parse(fs.readFileSync(ixPath, "utf8"));
for (const m of M) ix.modules[m.id] = { title: m.title, minutes: 6, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(ixPath, JSON.stringify(ix, null, 1));
const ocPath = path.join(ROOT, "prep/bank/overlay-counts.json");
const oc = JSON.parse(fs.readFileSync(ocPath, "utf8"));
oc.sets.maikbook2 = oc.sets.maikbook2 || {}; oc.sets.maikbook2.pathology = oc.sets.maikbook2.pathology || {};
for (const m of M) oc.sets.maikbook2.pathology[m.id] = 10;
fs.writeFileSync(ocPath, JSON.stringify(oc, null, 1));
const tPath = path.join(ROOT, "test/prep-books-mcqs.test.mjs");
let tc = fs.readFileSync(tPath, "utf8");
tc = tc.replace(/assert\.equal\(totalItems, 1080, "Expected 1050 high-yield verified MCQs in maikbook2 \(160 OBG \+ 360 pathology batch 2 \+ 120 pharmacology batch 2 \+ 270 ENT \+ 170 psychiatry\)"/, "assert.equal(totalItems, 1170, \"Expected 1170 high-yield verified MCQs in maikbook2 (160 OBG + 450 pathology batch 2 + 120 pharmacology batch 2 + 270 ENT + 170 psychiatry\")");
fs.writeFileSync(tPath, tc);
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "kbSkipped:", M.filter((m) => !m.kb).map((m) => m.id).join(","), "lesson failures:", fail);
